body:
Elasticsearch version: 7.14.0
Java version: 1.8.0_73
OS version: Windows 10

After upgrading to v7.14.0 significant_texts aggregations no longer work for multi fields. This was working before v7.14.0 . But now it doesn't work including v7.16.3.

Steps to reproduce:
```sh
# create the index
curl -XPUT "http://localhost:9200/test_index" -H 'Content-Type: application/json' -d '
{
  "mappings": {
    "properties": {
      "fullText": {
        "type": "text",
        "fields": {
          "eng": {
            "type": "text",
            "store": true,
            "analyzer": "english"
          }
        },
        "analyzer": "turkish"
      }
    }
  }
}'

# insert test data
curl -XPOST "http://localhost:9200/test_index/_doc" -H 'Content-Type: application/json' -d '
{  "fullText" : "apple banana pear melon"}'

curl -XPOST "http://localhost:9200/test_index/_doc" -H 'Content-Type: application/json' -d '
{  "fullText" : "apple banana pear"}'

curl -XPOST "http://localhost:9200/test_index/_doc" -H 'Content-Type: application/json' -d '
{  "fullText" : "apple banana melon"}'

curl -XPOST "http://localhost:9200/test_index/_doc" -H 'Content-Type: application/json' -d '
{  "fullText" : "apple pear melon"}'

curl -XPOST "http://localhost:9200/test_index/_doc" -H 'Content-Type: application/json' -d '
{  "fullText" : "apple melon"}'

curl -XPOST "http://localhost:9200/test_index/_doc" -H 'Content-Type: application/json' -d '
{  "fullText" : "elma muz armut kavun"}'

curl -XPOST "http://localhost:9200/test_index/_doc" -H 'Content-Type: application/json' -d '
{  "fullText" : "elma muz armut"}'

curl -XPOST "http://localhost:9200/test_index/_doc" -H 'Content-Type: application/json' -d '
{  "fullText" : "elma armut kavun"}'

# significant_texts aggregation test
curl -XGET "http://localhost:9200/test_index/_search" -H 'Content-Type: application/json' -d '
{
  "query": {
    "match_all": {}
  },
  "aggs": {
    "significant_texts": {
      "sampler": {
        "shard_size": 7
      },
      "aggregations": {
        "keywords": {
          "significant_text": {
            "field": "fullText.eng",
            "size": 1
          }
        }
      }
    }
  },
  "size": 0
}'
```

before v7.14.0 the result was as follows
```json
{
  "took" : 3,
  "timed_out" : false,
  "_shards" : {
    "total" : 1,
    "successful" : 1,
    "skipped" : 0,
    "failed" : 0
  },
  "hits" : {
    "total" : {
      "value" : 8,
      "relation" : "eq"
    },
    "max_score" : null,
    "hits" : [ ]
  },
  "aggregations" : {
    "significant_texts" : {
      "doc_count" : 7,
      "keywords" : {
        "doc_count" : 7,
        "bg_count" : 8,
        "buckets" : [
          {
            "key" : "appl",
            "doc_count" : 5,
            "score" : 0.10204081632653063,
            "bg_count" : 5
          }
        ]
      }
    }
  }
}
```

but after v7.14.0 the result is 
```json
{
  "took" : 16,
  "timed_out" : false,
  "_shards" : {
    "total" : 1,
    "successful" : 1,
    "skipped" : 0,
    "failed" : 0
  },
  "hits" : {
    "total" : {
      "value" : 8,
      "relation" : "eq"
    },
    "max_score" : null,
    "hits" : [ ]
  },
  "aggregations" : {
    "significant_texts" : {
      "doc_count" : 7,
      "keywords" : {
        "doc_count" : 7,
        "bg_count" : 8,
        "buckets" : [ ]
      }
    }
  }
}
```
